-- "Sobre a escola": resumos autorais a partir da Wikipedia PT (CC BY-SA), com a página como fonte.
-- Gerado por scripts/gerar-sql-historia.mjs em 2026-11-03. Só preenche o que está vazio
-- (coalesce), para não apagar nada curado à mão depois.
update escolas e set
  fundacao           = coalesce(e.fundacao, v.fundacao),
  bairro             = coalesce(e.bairro, v.bairro),
  cores              = coalesce(e.cores, v.cores),
  site_url           = coalesce(e.site_url, v.site),
  historia_md        = coalesce(e.historia_md, v.historia),
  historia_fonte_url = coalesce(e.historia_fonte_url, v.fonte)
from (values
  ('perola-negra', date '1973-08-07', 'Vila Madalena', null::text[], null, 'Nasceu em 1973 da fusão do GRES Acadêmicos de Vila Madalena com o Bloco Boca das Bruxas e se apresenta como "a joia rara do samba". Chegou ao Grupo Especial em 1976 e, desde então, alterna entre a elite e o acesso. Em 2025 foi campeã do Acesso 2 com o enredo Exu Mulher.', 'https://pt.wikipedia.org/wiki/P%C3%A9rola_Negra_(escola_de_samba)'),
  ('vai-vai', null::date, 'Bixiga', null::text[], 'https://www.vaivai.com.br/', 'A "Escola do Povo" nasceu no Bixiga, no Cordão Vae-Vae, criado por volta de 1930 por sambistas que tinham sido expulsos do time de futebol Cai-Cai. É a maior campeã do carnaval paulistano, com 15 títulos, o último em 2015.', 'https://pt.wikipedia.org/wiki/Vai-Vai'),
  ('barroca-zona-sul', date '1974-08-07', 'Vila Mariana', array['verde', 'rosa']::text[], null, 'Fundada em 1974 na Vila Mariana por Sebastião Eduardo do Amaral, o Pé Rachado, ex-presidente da Vai-Vai que teria sido incentivado por Cartola a criar a própria escola. O verde e rosa vem da madrinha, a Mangueira.', 'https://pt.wikipedia.org/wiki/Barroca_Zona_Sul'),
  ('dragoes-da-real', date '2000-03-17', null, null::text[], 'https://dragoesdareal.com.br/', 'Criada em 2000 por associados da torcida do São Paulo Futebol Clube. Foi campeã logo na estreia, em 2001, e subiu de grupo em sequência até chegar ao Anhembi.', 'https://pt.wikipedia.org/wiki/Drag%C3%B5es_da_Real_(escola_de_samba)'),
  ('academicos-do-tatuape', date '1952-10-26', 'Tatuapé', null::text[], 'https://www.academicosdotatuape.com.br/', 'Nasceu em 1952 como Unidos de Vila Santa Isabel e ganhou o nome atual em 1964, quando a sede foi para a rua principal do Tatuapé. O lema é "O Tatu que anda também samba".', 'https://pt.wikipedia.org/wiki/Acad%C3%AAmicos_do_Tatuap%C3%A9'),
  ('mocidade-unida-da-mooca', date '1987-03-18', 'Mooca', null::text[], null, 'Surgiu do Bloco Solta Franga e foi fundada oficialmente em 1987, na Mooca. Subiu de grupo com enredos sobre Pixinguinha (2014) e Carmen Miranda (2016).', 'https://pt.wikipedia.org/wiki/Mocidade_Unida_da_Mooca'),
  ('camisa-verde-e-branco', date '1953-09-04', 'Barra Funda', array['verde', 'branco']::text[], null, 'Considerada o berço do samba paulistano, tem raízes no Grupo Carnavalesco Barra Funda, de 1914, cujos foliões saíam de camisa verde e calça branca. Foi reorganizada em 1953 como Cordão Mocidade Camisa Verde e Branco e soma 9 títulos.', 'https://pt.wikipedia.org/wiki/Camisa_Verde_e_Branco'),
  ('imperio-de-casa-verde', date '1994-02-27', 'Casa Verde', null::text[], null, 'Fundada em 1994 por dissidentes da Unidos do Peruche, teve uma das subidas mais rápidas do carnaval paulistano: foi campeã no primeiro desfile e ganhou o primeiro título do Grupo Especial com apenas onze anos de vida.', 'https://pt.wikipedia.org/wiki/Imp%C3%A9rio_de_Casa_Verde'),
  ('gavioes-da-fiel', date '1969-01-01', 'Bom Retiro', null::text[], 'https://gavioes.com.br/', 'Maior torcida organizada do Corinthians, criada em 1969, é também escola de samba: o carnaval e o futebol fazem parte da mesma entidade, com sede no Bom Retiro.', 'https://pt.wikipedia.org/wiki/Gavi%C3%B5es_da_Fiel'),
  ('mocidade-alegre', date '1967-09-24', null, null::text[], 'https://www.mocidadealegre.com.br/', 'Nasceu de um bloco de foliões do Bom Retiro dos anos 1950 e se intitula a "Morada do Samba". Tem 13 títulos do Grupo Especial, o último em 2026, e é conhecida pelos carnavais de temática afro.', 'https://pt.wikipedia.org/wiki/Mocidade_Alegre'),
  ('tom-maior', date '1973-02-14', 'Sumaré', array['vermelho', 'amarelo', 'branco']::text[], null, 'O nome vem de versos de Martinho da Vila. Fundada por Hélio Bagunça com sambistas da Camisa Verde e Branco, nasceu no Sumaré, estreou em 1974 e chegou ao Grupo Especial pela primeira vez em 1977.', 'https://pt.wikipedia.org/wiki/Tom_Maior'),
  ('estrela-do-terceiro-milenio', null::date, 'Grajaú', array['azul', 'verde', 'branco', 'vermelho']::text[], null, 'Escola do Grajaú, no extremo sul da cidade, batizada em alusão à virada do milênio. A coruja do símbolo vem da casa de shows Corujão, onde foram os primeiros ensaios, e a madrinha é a Rosas de Ouro.', 'https://pt.wikipedia.org/wiki/Estrela_do_Terceiro_Mil%C3%AAnio'),
  ('colorado-do-bras', date '1975-10-01', 'Brás', null::text[], null, 'Fundada em 1975 no Brás, a partir da torcida de um time de várzea, teve ao seu lado sambistas como Geraldo Filme. O samba de 1988, "Catopês do Milho Verde", é lembrado como um dos melhores da história do carnaval paulistano.', 'https://pt.wikipedia.org/wiki/Colorado_do_Br%C3%A1s'),
  ('academicos-do-tucuruvi', date '1976-02-01', 'Tucuruvi', array['azul', 'branco']::text[], 'http://academicosdotucuruvi.com.br/', 'Fundada em 1976 por moradores do bairro, tem um gafanhoto como símbolo, porque "Tucuruvi" quer dizer "gafanhoto verde" em tupi. É azul e branco desde os anos 1980, e seu melhor resultado foi o vice-campeonato de 2011.', 'https://pt.wikipedia.org/wiki/Acad%C3%AAmicos_do_Tucuruvi'),
  ('x-9-paulistana', null::date, 'Vila Guilherme', null::text[], null, 'Nasceu na Parada Inglesa, entre amigos de um time de futebol, e herdou o nome da X-9 de Santos. Chamava-se Filhotes da X-9 até 1986, chegou ao Grupo Especial em 1995 e é bicampeã da elite.', 'https://pt.wikipedia.org/wiki/X-9_Paulistana'),
  ('dom-bosco-de-itaquera', null::date, 'Itaquera', null::text[], null, 'Escola de Itaquera criada a partir da Obra Social Dom Bosco, mantida pela Igreja Católica. O fundador é o padre salesiano Rosalvino Morán Viñayo.', 'https://pt.wikipedia.org/wiki/Dom_Bosco_(escola_de_samba)'),
  ('rosas-de-ouro', date '1971-01-01', 'Brasilândia', null::text[], null, 'Fundada em 1971 na Brasilândia, foi presidida por Eduardo Basílio da fundação até 2003. O nome vem da Rosa de Ouro, condecoração dada pelos papas. Campeã em 2025, caiu para o Acesso 1 no ano seguinte.', 'https://pt.wikipedia.org/wiki/Rosas_de_Ouro'),
  ('aguia-de-ouro', date '1976-05-09', 'Pompeia', array['azul', 'dourado', 'branco']::text[], null, 'Fundada em 1976 na Pompeia por jogadores do time de várzea Faísca de Ouro. Ganhou o primeiro título do Grupo Especial em 2020.', 'https://pt.wikipedia.org/wiki/%C3%81guia_de_Ouro'),
  ('unidos-de-vila-maria', date '1954-01-10', 'Jardim Japão', null::text[], null, 'Uma das escolas mais tradicionais de São Paulo, fundada em 1954. Fica no Jardim Japão, no distrito da Vila Maria.', 'https://pt.wikipedia.org/wiki/Unidos_de_Vila_Maria'),
  ('mancha-verde', date '1995-10-18', null, null::text[], null, 'Ligada à torcida do Palmeiras, foi oficializada em outubro de 1995, primeiro como bloco carnavalesco. Estreou em 1996 com um enredo sobre a destruição da natureza.', 'https://pt.wikipedia.org/wiki/Mancha_Verde'),
  ('morro-da-casa-verde', date '1962-04-06', 'Casa Verde', array['verde', 'rosa']::text[], null, 'Fundada em 1962 por Zezinho do Banjo, participou do primeiro desfile organizado em São Paulo, em 1968. O verde e rosa homenageia a Mangueira, escola do coração do fundador.', 'https://pt.wikipedia.org/wiki/Morro_da_Casa_Verde'),
  ('independente-tricolor', null::date, 'Vila Guilherme', null::text[], null, 'Vem da Torcida Tricolor Independente, do São Paulo. Depois de anos fora do carnaval oficial, voltou como escola de samba e estreou em 2010 pelo Grupo 4 da UESP.', 'https://pt.wikipedia.org/wiki/Independente_Tricolor'),
  ('unidos-de-santa-barbara', null::date, 'Itaim Paulista', null::text[], null, 'Nasceu como bloco em 1988, no Itaim Paulista, e leva o nome da santa de devoção dos fundadores. Virou escola de samba em 2009 e emendou quatro acessos seguidos até chegar ao Anhembi em 2012.', 'https://pt.wikipedia.org/wiki/Unidos_de_Santa_B%C3%A1rbara'),
  ('brinco-da-marquesa', null::date, 'Vila Brasilina', null::text[], null, null, null),
  ('unidos-do-peruche', date '1956-01-04', 'Limão', array['verde', 'amarelo', 'azul', 'branco']::text[], null, 'Criada nos anos 1950 por amigos que saíam na escola Lavapés, nasceu no Parque Peruche e é chamada de "a filial do samba". Tem as cores da bandeira do Brasil, foi tricampeã do Grupo Especial nos anos 1960 e já teve Jamelão entre seus intérpretes.', 'https://pt.wikipedia.org/wiki/Unidos_do_Peruche'),
  ('imperatriz-da-pauliceia', null::date, 'Vila Fidelis Ribeiro', null::text[], null, null, null),
  ('imperador-do-ipiranga', date '1968-01-01', 'Vila Carioca', null::text[], null, 'Fundada em 1968 por moradores de Heliópolis, da Vila Carioca e da Vila Independência, homenageia Dom Pedro I no nome. O primeiro desfile foi um protesto contra as enchentes do bairro, com carros alegóricos imitando barcos.', 'https://pt.wikipedia.org/wiki/Imperador_do_Ipiranga'),
  ('nene-de-vila-matilde', date '1949-01-01', 'Vila Matilde', null::text[], null, 'Fundada em 1949 por Alberto Alves da Silva, o Seu Nenê, que a presidiu por 47 anos. Tem 11 títulos do Grupo Especial, é afilhada da Portela e foi a primeira escola de samba com quadra coberta, em 1968.', 'https://pt.wikipedia.org/wiki/Nen%C3%AA_de_Vila_Matilde'),
  ('unidos-de-sao-lucas', null::date, 'Parque São Lucas', null::text[], null, 'Nasceu de um bloco de torcedores do São Cristóvão Bandeirante e virou escola de samba em 1980, campeã logo no primeiro desfile. Chegou ao Grupo Especial pela primeira vez em 2001.', 'https://pt.wikipedia.org/wiki/Unidos_de_S%C3%A3o_Lucas'),
  ('torcida-jovem', null::date, null, null::text[], null, 'É a escola de samba da Torcida Jovem do Santos, torcida organizada fundada em 1969 no Brás, em São Paulo. Desfila como escola de samba desde 2003.', 'https://pt.wikipedia.org/wiki/Torcida_Jovem_do_Santos'),
  ('primeira-da-cidade-lider', date '1993-01-01', 'Cidade Líder', null::text[], null, 'Fundada em 1993 pelo compositor Odair Fala Macio, na Cidade Líder. Voltou a desfilar em 2015 com os irmãos Rodrigo e Rodolfo Minuetto à frente e estreou no Anhembi em 2019.', 'https://pt.wikipedia.org/wiki/Primeira_da_Cidade_L%C3%ADder'),
  ('camisa-12', date '1996-01-12', 'Vila Maria', null::text[], null, 'Ligada à torcida organizada Camisa 12, nasceu como bloco em 1984 na Vila Maria e virou escola de samba em janeiro de 1996.', 'https://pt.wikipedia.org/wiki/Camisa_12_(escola_de_samba)')
) as v(slug, fundacao, bairro, cores, site, historia, fonte)
where e.slug = v.slug;
